", "new_string": "import copy
import os
import tomllib

from .defaults import DEFAULTS


def _merge(base, override):
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            _merge(base[key], value)
        else:
            base[key] = value
    return base


def _parse_bool(value):
    """Parse the boolean spellings accepted for environment overrides."""
    normalized = value.strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"invalid boolean value: {value!r}")


def _convert_env_value(value, current):
    """Convert an environment string to the type of the value it replaces."""
    value = str(value)
    if isinstance(current, bool):
        return _parse_bool(value)
    if isinstance(current, int):
        return int(value)
    if isinstance(current, float):
        return float(value)
    if isinstance(current, str):
        return value
    raise TypeError(
        f"cannot override {type(current).__name__} configuration value from the environment"
    )


def _apply_env_overrides(config, env):
    for name, value in env.items():
        if not isinstance(name, str) or not name.startswith("APP_"):
            continue

        suffix = name[4:]
        # Environment variable names are specified in upper case.  Do not
        # accidentally interpret a similarly named, differently-cased variable.
        if suffix != suffix.upper():
            continue

        parts = suffix.split("_", 1)
        if len(parts) != 2:
            continue

        section_name, key_name = (part.lower() for part in parts)
        section = config.get(section_name)
        if not isinstance(section, dict) or key_name not in section:
            continue

        section[key_name] = _convert_env_value(value, section[key_name])


def load_config(path=None, env=None):
    """Return the effective configuration.

    The TOML file at ``path`` overrides :data:`DEFAULTS`, and environment
    variables named ``APP_<SECTION>_<KEY>`` override the merged result.
    """
    config = copy.deepcopy(DEFAULTS)
    if path is not None:
        with open(path, "rb") as fh:
            _merge(config, tomllib.load(fh))

    if env is None:
        env = os.environ
    _apply_env_overrides(config, env)
    return config
